window.MG_LAZY_DATA["data/lazy/owner-courses/b310-dd62b98c0a63a28b.json"]={sha256:"dd62b98c0a63a28badd9537034aac2208d90da06f2ff3bc1d3d70cabe7f9f5f7",value:{"id":"b310","title":"法國東南高速鐵路","titleEn":"LGV Sud-Est","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"以法國東南高速鐵路開創高速服務的歷史為背景，比較高速專用線和既有線銜接時的設計目標。課程將線形、牽引、分相、訊號與維護放在共同時間尺度，檢查一項速度提升是否需要多個子系統共同改變。","summaryEn":"Use the introduction of French high-speed service on LGV Sud-Est to compare dedicated high-speed alignment with connections to conventional infrastructure. Place geometry, traction, neutral sections, signalling and maintenance on a common time axis. Investigate whether a speed increase demands coordinated changes in several subsystems rather than a single adjustment to motor output.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、軌道進入、牽引供電隔離或列車營運許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, track-access, traction-power isolation or train-operation permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"rail-highspeed","subcategoryTitle":"高速鐵路系統","subcategoryTitleEn":"High-speed rail systems","learningTrack":"rail","learningSubdiscipline":"rail-highspeed","learningTags":["rail","rail-highspeed","rail"],"architectureFamily":"rail-system","architectureNodes":[["路線與土建","Alignment and civil works"],["車輛與接觸","Vehicle and contact"],["牽引供電","Traction supply"],["行車控制","Movement control"],["車站與旅客","Stations and passengers"],["監測與維護","Monitoring and maintenance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[3,4],[4,5],[5,0],[5,3]],"diagram":{"type":"rail-system","labels":["路線與土建","車輛與接觸","牽引供電","行車控制","車站與旅客"],"labelsEn":["Alignment and civil works","Vehicle and contact","Traction supply","Movement control","Stations and passengers"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合原創算例：單元 1 得 residual=0.15156 m/s^2；單元 2 得 climbing=2401.488 kW；單元 3 得 power=2183.966 kW。上述三個結果使用各單元明示的不同邊界，不能任意相加或視為實際工程實測值。以第一單元 v 的擾動測試，結果改為 0.3481956 m/s^2；學徒需先比較單位、敏感度和假設，再決定是否要細化模型。以法國東南高速鐵路開創高速服務的歷史為背景，比較高速專用線和既有線銜接時的設計目標。課程將線形、牽引、分相、訊號與維護放在共同時間尺度，檢查一項速度提升是否需要多個子系統共同改變。 最終交付應保留原始輸入、測點時間戳、誤差範圍與無法由簡化式證明的結論。","textEn":"Integrated original exercise: unit 1 gives residual=0.15156 m/s^2; unit 2 gives climbing=2401.488 kW; unit 3 gives power=2183.966 kW. These three results use different explicit boundaries and must not be added or presented as measurements of the real railway. Perturbing v in the first unit changes its result to 0.3481956 m/s^2. Compare units, sensitivity and assumptions before deciding which model needs refinement. Use the introduction of French high-speed service on LGV Sud-Est to compare dedicated high-speed alignment with connections to conventional infrastructure. Place geometry, traction, neutral sections, signalling and maintenance on a common time axis. Investigate whether a speed increase demands coordinated changes in several subsystems rather than a single adjustment to motor output. The final submission should retain original inputs, measurement timestamps, uncertainty ranges and conclusions that the simplified expressions cannot establish.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":16,"enrichmentVersion":16,"stages":[{"id":"b310-v16-s1","title":"曲線超高與未平衡加速度與坡度阻力與爬坡功率","titleEn":"Cant and unbalanced acceleration & Gradient resistance and climbing power","description":"本階段聚焦「曲線超高與未平衡加速度」與「坡度阻力與爬坡功率」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Cant and unbalanced acceleration\" and \"Gradient resistance and climbing power\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b310-v16-01","title":"曲線超高與未平衡加速度：機制與系統路徑","titleEn":"Cant and unbalanced acceleration: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":[],"objective":"說明「曲線超高與未平衡加速度」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Cant and unbalanced acceleration” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。超高平衡速度只對特定半徑和速度成立，慢車可能出現超高過剩；不能把增加超高當成所有車種都受益的措施。 殘餘加速度的正負表示側向作用方向，而不是安全與危險的二元判斷。半徑、軌距與高差必須使用一致長度單位，車體感受還會受到懸吊轉角影響。 用同一曲線比較高速專用服務與低速轉線時的橫向需求。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「曲線超高與未平衡加速度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration. Equilibrium cant applies to one radius and speed. A slower service can experience cant excess, so increasing cant does not improve every train condition. The sign of residual acceleration identifies its lateral direction, not a binary safe-unsafe outcome. Radius, gauge and rail-level difference require consistent length units. Carbody response is additionally affected by suspension rotation, which this geometric estimate does not resolve. Compare lateral demand on one curve for dedicated high-speed running and slower connecting movements. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Cant and unbalanced acceleration” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2.","failure":"常見誤解：「任何速度下增加超高都一定減少車內橫向加速度」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Increasing cant always reduces lateral acceleration at every operating speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「曲線超高與未平衡加速度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Cant and unbalanced acceleration”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-01-k1","title":"曲線超高與未平衡加速度","titleEn":"Cant and unbalanced acceleration","text":"曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。超高平衡速度只對特定半徑和速度成立，慢車可能出現超高過剩；不能把增加超高當成所有車種都受益的措施。","textEn":"On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration. Equilibrium cant applies to one radius and speed.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：任何速度下增加超高都一定減少車內橫向加速度 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Increasing cant always reduces lateral acceleration at every operating speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「曲線超高與未平衡加速度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cant and unbalanced acceleration\" is correct?","options":["任何速度下增加超高都一定減少車內橫向加速度","曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Increasing cant always reduces lateral acceleration at every operating speed.","On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":1,"explanation":"曲線需求的向心加速度由重力沿軌道平面的分量與輪軌側向作用共同提供。 其餘選項是常見誤解。","explanationEn":"On a curve, the component of gravity in the track plane and wheel-rail lateral forces together provide centripetal acceleration. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b310-v16-02","title":"曲線超高與未平衡加速度：定量估算","titleEn":"Cant and unbalanced acceleration: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-01"],"objective":"以數值模型估算「曲線超高與未平衡加速度」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cant and unbalanced acceleration” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2。敏感度：v 單獨增加百分之十至 67.32 m/s，其餘固定，結果為 0.3481956 m/s^2。模型邊界：小角度近似與剛性車體；未計懸吊側滾、動態輪重減載和規範允收值。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2. Sensitivity: v, increase this input alone by ten percent, to 67.32 m/s, with all other inputs fixed, gives 0.3481956 m/s^2. Model boundary: Small-angle approximation and rigid body; suspension roll, dynamic wheel unloading and acceptance limits are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。","observationEn":"How to cross-check: Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2。敏感度：v 單獨增加百分之十至 67.32 m/s，其餘固定，結果為 0.3481956 m/s^2。模型邊界：小角度近似與剛性車體；未計懸吊側滾、動態輪重減載和規範允收值。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2. Sensitivity: v, increase this input alone by ten percent, to 67.32 m/s, with all other inputs fixed, gives 0.3481956 m/s^2. Model boundary: Small-angle approximation and rigid body; suspension roll, dynamic wheel unloading and acceptance limits are excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「曲線超高與未平衡加速度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cant and unbalanced acceleration\", which statement holds?","options":["只要靜態接觸線高度正確就能保證高速受流品質","降低目標速度時可忽略初速與目標速度的平方差","原創假想算例，全部輸入均非本工程操作參數：v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m。"],"optionsEn":["Correct static contact-wire height alone guarantees good current collection at high speed.","Reducing target speed allows the squared-speed difference to be ignored.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m；計算：residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=61.2 m/s; R=4000 m; gauge=1.5 m; cant=0.12 m; calculation: residual=v*v/R-9.81*cant/gauge=0.15156 m/s^2. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b310-v16-03","title":"曲線超高與未平衡加速度：試驗與驗證","titleEn":"Cant and unbalanced acceleration: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「曲線超高與未平衡加速度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Cant and unbalanced acceleration” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。 用實測半徑和高差重算平衡速度，保留感測器安裝角的校正值及量測不確定度。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings. Recalculate equilibrium speed from measured radius and cant, retaining mounting-angle corrections and uncertainty for the acceleration sensor. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：選兩種速度共同計算殘餘加速度，找出符號反轉位置，說明為何混合服務需要速度分布而非單一最高速度。 再以本單元 v 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate residual acceleration for two speeds, locate its sign reversal, and explain why mixed services require a speed distribution rather than one maximum speed. Also recalculate residual for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。 用實測半徑和高差重算平衡速度，保留感測器安裝角的校正值及量測不確定度。","textEn":"Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings. Recalculate equilibrium speed from measured radius and cant, retaining mounting-angle corrections and uncertainty for the acceleration sensor.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"選兩種速度共同計算殘餘加速度，找出符號反轉位置，說明為何混合服務需要速度分布而非單一最高速度。 再以本單元 v 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate residual acceleration for two speeds, locate its sign reversal, and explain why mixed services require a speed distribution rather than one maximum speed. Also recalculate residual for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「曲線超高與未平衡加速度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cant and unbalanced acceleration\"?","options":["在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","疲勞損傷只取決於通過列車總數而不受應力幅影響"],"optionsEn":["Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","Fatigue damage depends only on train count and is independent of stress range."],"answer":0,"explanation":"在相同半徑區段量測軌面高差與橫向加速度，扣除感測器安裝角度，並把車體讀值與軌道平面讀值分開記錄。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure rail level difference and lateral acceleration on the same curve, remove sensor mounting angle, and distinguish carbody readings from track-plane readings. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b310-v16-04","title":"曲線超高與未平衡加速度：失效診斷","titleEn":"Cant and unbalanced acceleration: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-03"],"objective":"從症狀倒推「曲線超高與未平衡加速度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Cant and unbalanced acceleration” and propose discriminating checks, corrective actions and prevention.","instruction":"只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 需核對高差符號與曲線方向，防止左右軌互換。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. Check cant sign against curve direction to prevent swapping the inner and outer rails. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：用同一曲線比較高速專用服務與低速轉線時的橫向需求。","observationEn":"Link to the mechanism: Compare lateral demand on one curve for dedicated high-speed running and slower connecting movements.","failure":"誤判風險：若相信「任何速度下增加超高都一定減少車內橫向加速度」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Increasing cant always reduces lateral acceleration at every operating speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 需核對高差符號與曲線方向，防止左右軌互換。","textEn":"Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. Check cant sign against curve direction to prevent swapping the inner and outer rails.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「曲線超高與未平衡加速度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cant and unbalanced acceleration\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":1,"explanation":"只依高速通過最佳化超高，可能讓慢車或停車承受反向側向力；感測器橫滾又會把重力投影混入振動訊號。 需以量測區分可能原因。","explanationEn":"Cant optimised only for fast trains can impose reverse lateral loading on slow or stopped trains; sensor roll also mixes gravity into vibration measurements. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b310-v16-05","title":"坡度阻力與爬坡功率：機制與系統路徑","titleEn":"Gradient resistance and climbing power: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-04"],"objective":"說明「坡度阻力與爬坡功率」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Gradient resistance and climbing power” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。功率還與速度相乘，因此相同牽引力下高速爬坡更耗功率；下坡則需處理持續制動能量而非僅一次停車。 坡度以升高量除以水平距離表示，百分比與小數不可混用。此項只表示重力位能增加的速率，總牽引功率還要加上加速、滾動、氣動及轉換損失。 將坡度阻力與加速功率分開，檢查長坡頂部的速度裕度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「坡度阻力與爬坡功率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Climbing raises gravitational potential energy. For small gradients, the along-track gravity force is approximately weight times gradient. Multiplication by speed gives power, making faster climbing more demanding at equal force; descending requires continuous energy management rather than merely one stopping event. Gradient is rise divided by horizontal distance, so percentage and decimal representations must not be mixed. This term only gives the rate of gravitational potential-energy increase. Total traction demand also includes acceleration, rolling resistance, aerodynamics and conversion losses. Separate gradient resistance from acceleration power and inspect speed margin near a long climb’s summit. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Gradient resistance and climbing power” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mass=306000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2401.488 kW。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=306000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2401.488 kW.","failure":"常見誤解：「長下坡只需通過一次緊急停車試驗就能驗證持續制動」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"One emergency stop test verifies continuous braking capability on a long descent.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「坡度阻力與爬坡功率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Gradient resistance and climbing power”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-05-k1","title":"坡度阻力與爬坡功率","titleEn":"Gradient resistance and climbing power","text":"列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。功率還與速度相乘，因此相同牽引力下高速爬坡更耗功率；下坡則需處理持續制動能量而非僅一次停車。","textEn":"Climbing raises gravitational potential energy. For small gradients, the along-track gravity force is approximately weight times gradient.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：長下坡只需通過一次緊急停車試驗就能驗證持續制動 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: One emergency stop test verifies continuous braking capability on a long descent. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「坡度阻力與爬坡功率」，下列哪一項敘述正確？","questionEn":"Which statement about \"Gradient resistance and climbing power\" is correct?","options":["長下坡只需通過一次緊急停車試驗就能驗證持續制動","速度增加一成時克服空氣阻力的功率只增加一成","列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。"],"optionsEn":["One emergency stop test verifies continuous braking capability on a long descent.","A ten percent speed increase raises aerodynamic power by only ten percent.","Climbing raises gravitational potential energy."],"answer":2,"explanation":"列車爬坡需提高重力位能，坡度小時沿線重力分量約等於重量乘坡度。 其餘選項是常見誤解。","explanationEn":"Climbing raises gravitational potential energy. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b310-v16-06","title":"坡度阻力與爬坡功率：定量估算","titleEn":"Gradient resistance and climbing power: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-05"],"objective":"以數值模型估算「坡度阻力與爬坡功率」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Gradient resistance and climbing power” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mass=306000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2401.488 kW。敏感度：mass 單獨增加百分之十至 336600 kg，其餘固定，結果為 2641.637 kW。模型邊界：小坡度且定速；不含空阻、輪阻、加速與傳動損失。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=306000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2401.488 kW. Sensitivity: mass, increase this input alone by ten percent, to 336600 kg, with all other inputs fixed, gives 2641.637 kW. Model boundary: Small gradient and constant speed; aerodynamic drag, rolling resistance, acceleration and drive losses are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。","observationEn":"How to cross-check: Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mass=306000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2401.488 kW。敏感度：mass 單獨增加百分之十至 336600 kg，其餘固定，結果為 2641.637 kW。模型邊界：小坡度且定速；不含空阻、輪阻、加速與傳動損失。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=306000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2401.488 kW. Sensitivity: mass, increase this input alone by ten percent, to 336600 kg, with all other inputs fixed, gives 2641.637 kW. Model boundary: Small gradient and constant speed; aerodynamic drag, rolling resistance, acceleration and drive losses are excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「坡度阻力與爬坡功率」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Gradient resistance and climbing power\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：mass=306000 kg; gradient=0.02 1; v=40 m/s。","無電區長度改變不會影響列車離開時的速度","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Original hypothetical exercise.","Changing the length of an unpowered section cannot change exit speed.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mass=306000 kg; gradient=0.02 1; v=40 m/s；計算：climbing=mass*9.81*gradient*v/1000=2401.488 kW。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=306000 kg; gradient=0.02 1; v=40 m/s; calculation: climbing=mass*9.81*gradient*v/1000=2401.488 kW. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b310-v16-07","title":"坡度阻力與爬坡功率：試驗與驗證","titleEn":"Gradient resistance and climbing power: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「坡度阻力與爬坡功率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Gradient resistance and climbing power” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。 由高程剖面核對坡度，使用同一時間窗比對速度與牽引功率，另列非重力負載。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent. Check gradient from the elevation profile, compare speed and traction power over one time window, and list non-gravitational loads separately. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用相同高差設計長緩坡與短陡坡，對比理想位能和峰值功率，指出兩者為何不能用同一項設備額定值評估。 再以本單元 mass 的對照值重算 climbing，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Design a long gentle and short steep climb with equal height gain, compare ideal energy and peak power, and explain why one equipment rating cannot evaluate both. Also recalculate climbing for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。 由高程剖面核對坡度，使用同一時間窗比對速度與牽引功率，另列非重力負載。","textEn":"Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent. Check gradient from the elevation profile, compare speed and traction power over one time window, and list non-gravitational loads separately.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"用相同高差設計長緩坡與短陡坡，對比理想位能和峰值功率，指出兩者為何不能用同一項設備額定值評估。 再以本單元 mass 的對照值重算 climbing，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Design a long gentle and short steep climb with equal height gain, compare ideal energy and peak power, and explain why one equipment rating cannot evaluate both. Also recalculate climbing for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「坡度阻力與爬坡功率」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Gradient resistance and climbing power\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。","快慢車平均速度不同也不會影響同線時刻表容量"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent.","Different fast and slow train speeds do not affect shared-line timetable capacity."],"answer":1,"explanation":"以路線縱斷面和列車速度重建位能變化，對照受電功率積分；坡度資料與里程基準必須一致。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconstruct potential-energy change from the vertical alignment and train speed, compare it with integrated line power, and keep gradient and distance datums consistent. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b310-v16-08","title":"坡度阻力與爬坡功率：失效診斷","titleEn":"Gradient resistance and climbing power: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-07"],"objective":"從症狀倒推「坡度阻力與爬坡功率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Gradient resistance and climbing power” and propose discriminating checks, corrective actions and prevention.","instruction":"忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 功率不足時須分辨坡度阻力與黏著限制，不能只加大電流。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. When power is insufficient, distinguish gradient resistance from adhesion limits rather than only increasing current. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將坡度阻力與加速功率分開，檢查長坡頂部的速度裕度。","observationEn":"Link to the mechanism: Separate gradient resistance from acceleration power and inspect speed margin near a long climb’s summit.","failure":"誤判風險：若相信「長下坡只需通過一次緊急停車試驗就能驗證持續制動」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"One emergency stop test verifies continuous braking capability on a long descent.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 功率不足時須分辨坡度阻力與黏著限制，不能只加大電流。","textEn":"Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. When power is insufficient, distinguish gradient resistance from adhesion limits rather than only increasing current.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「坡度阻力與爬坡功率」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Gradient resistance and climbing power\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","速度增加一成時克服空氣阻力的功率只增加一成","忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","A ten percent speed increase raises aerodynamic power by only ten percent.","Ignoring sustained downhill heat confuses short-term braking capability with continuous rating."],"answer":2,"explanation":"忽略長下坡持續熱負荷會把短時煞車能力誤當連續能力；坡度正負號錯誤則會把耗能段當成回收段。 需以量測區分可能原因。","explanationEn":"Ignoring sustained downhill heat confuses short-term braking capability with continuous rating; a gradient-sign error can mislabel an energy-consuming section as regenerative. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b310-v16-s2","title":"空氣阻力與牽引功率與接觸線張力波速","titleEn":"Aerodynamic drag and traction power & Contact-wire tension wave speed","description":"本階段聚焦「空氣阻力與牽引功率」與「接觸線張力波速」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Aerodynamic drag and traction power\" and \"Contact-wire tension wave speed\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b310-v16-09","title":"空氣阻力與牽引功率：機制與系統路徑","titleEn":"Aerodynamic drag and traction power: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-08"],"objective":"說明「空氣阻力與牽引功率」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Aerodynamic drag and traction power” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"高速列車的空氣阻力與速度平方成正比，而克服此阻力所需功率再乘一次速度，形成三次方敏感度。有效阻力面積包含外形與附屬物影響；會車、隧道及側風會使定常自由場模型失效。 阻力是速度平方關係，而牽引功率還要乘一次速度。把逆風納入時應使用相對空氣速度；滾動阻力與坡度功率是另外的能量途徑，不能被此氣動項取代。 評估空氣阻力的速度三次方功率變化，保留阻力係數假設。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「空氣阻力與牽引功率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Aerodynamic drag scales with speed squared, and the power needed to overcome it adds another speed factor. Effective drag area includes shape and attachments. Passing trains, tunnels and crosswinds can invalidate the steady open-air approximation even when the nominal speed remains unchanged. Drag varies with squared speed, while traction power introduces another speed factor. Headwind requires relative air speed. Rolling resistance and gradient power are separate energy paths and cannot be replaced by this aerodynamic term. Evaluate cubic aerodynamic power growth while retaining the assumed drag coefficient. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Aerodynamic drag and traction power” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s；計算：power=0.5*rho*CdA*v**3/1000=2183.966 kW。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s; calculation: power=0.5*rho*CdA*v**3/1000=2183.966 kW.","failure":"常見誤解：「速度增加一成時克服空氣阻力的功率只增加一成」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A ten percent speed increase raises aerodynamic power by only ten percent.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「空氣阻力與牽引功率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Aerodynamic drag and traction power”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-09-k1","title":"空氣阻力與牽引功率","titleEn":"Aerodynamic drag and traction power","text":"高速列車的空氣阻力與速度平方成正比，而克服此阻力所需功率再乘一次速度，形成三次方敏感度。有效阻力面積包含外形與附屬物影響；會車、隧道及側風會使定常自由場模型失效。","textEn":"Aerodynamic drag scales with speed squared, and the power needed to overcome it adds another speed factor. Effective drag area includes shape and attachments.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：速度增加一成時克服空氣阻力的功率只增加一成 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A ten percent speed increase raises aerodynamic power by only ten percent. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「空氣阻力與牽引功率」，下列哪一項敘述正確？","questionEn":"Which statement about \"Aerodynamic drag and traction power\" is correct?","options":["高速列車的空氣阻力與速度平方成正比，而克服此阻力所需功率再乘一次速度，形成三次方敏感度。","速度增加一成時克服空氣阻力的功率只增加一成","只要靜態接觸線高度正確就能保證高速受流品質"],"optionsEn":["Aerodynamic drag scales with speed squared, and the power needed to overcome it adds another speed factor.","A ten percent speed increase raises aerodynamic power by only ten percent.","Correct static contact-wire height alone guarantees good current collection at high speed."],"answer":0,"explanation":"高速列車的空氣阻力與速度平方成正比，而克服此阻力所需功率再乘一次速度，形成三次方敏感度。 其餘選項是常見誤解。","explanationEn":"Aerodynamic drag scales with speed squared, and the power needed to overcome it adds another speed factor. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b310-v16-10","title":"空氣阻力與牽引功率：定量估算","titleEn":"Aerodynamic drag and traction power: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-09"],"objective":"以數值模型估算「空氣阻力與牽引功率」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Aerodynamic drag and traction power” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s；計算：power=0.5*rho*CdA*v**3/1000=2183.966 kW。敏感度：v 單獨增加百分之十至 78.54 m/s，其餘固定，結果為 2906.859 kW。模型邊界：定常靜風且阻力面積固定；僅空氣阻力功率，不含輪軌阻力與效率。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s; calculation: power=0.5*rho*CdA*v**3/1000=2183.966 kW. Sensitivity: v, increase this input alone by ten percent, to 78.54 m/s, with all other inputs fixed, gives 2906.859 kW. Model boundary: Steady still air and constant drag area; aerodynamic power only, excluding rolling resistance and conversion losses. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在相同編組與天候下做不同速度的惰行分析，記錄風速方向與車頭迎角，避免把坡度造成的加速度誤判成空阻。","observationEn":"How to cross-check: Compare coast-down observations across speeds with the same consist, log wind speed and direction, and separate gradient acceleration from aerodynamic resistance.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s；計算：power=0.5*rho*CdA*v**3/1000=2183.966 kW。敏感度：v 單獨增加百分之十至 78.54 m/s，其餘固定，結果為 2906.859 kW。模型邊界：定常靜風且阻力面積固定；僅空氣阻力功率，不含輪軌阻力與效率。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s; calculation: power=0.5*rho*CdA*v**3/1000=2183.966 kW. Sensitivity: v, increase this input alone by ten percent, to 78.54 m/s, with all other inputs fixed, gives 2906.859 kW. Model boundary: Steady still air and constant drag area; aerodynamic power only, excluding rolling resistance and conversion losses.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「空氣阻力與牽引功率」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Aerodynamic drag and traction power\", which statement holds?","options":["降低目標速度時可忽略初速與目標速度的平方差","原創假想算例，全部輸入均非本工程操作參數：rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s。","疲勞損傷只取決於通過列車總數而不受應力幅影響"],"optionsEn":["Reducing target speed allows the squared-speed difference to be ignored.","Original hypothetical exercise.","Fatigue damage depends only on train count and is independent of stress range."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s；計算：power=0.5*rho*CdA*v**3/1000=2183.966 kW。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: rho=1.2 kg/m^3; CdA=10 m^2; v=71.4 m/s; calculation: power=0.5*rho*CdA*v**3/1000=2183.966 kW. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b310-v16-11","title":"空氣阻力與牽引功率：試驗與驗證","titleEn":"Aerodynamic drag and traction power: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「空氣阻力與牽引功率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Aerodynamic drag and traction power” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在相同編組與天候下做不同速度的惰行分析，記錄風速方向與車頭迎角，避免把坡度造成的加速度誤判成空阻。 同步紀錄風向風速與地速，將穩速段牽引功率扣除可辨識的坡度和輔助負載。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare coast-down observations across speeds with the same consist, log wind speed and direction, and separate gradient acceleration from aerodynamic resistance. Record wind vector and ground speed together, then remove identifiable gradient and auxiliary loads from steady-running traction power. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對速度增加一成與阻力面積減少一成各算一次，對比功率節省，並把輪軌阻力另列以避免誇大整列節能比例。 再以本單元 v 的對照值重算 power，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate a ten percent speed increase and a ten percent drag-area reduction separately, compare power changes, and keep rolling resistance separate from whole-train energy savings. Also recalculate power for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：車底設備改變或側風會改變有效阻力面積；若只以單一速度校準，仍可能在另一速度得到錯誤牽引需求。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Underbody changes and crosswinds alter effective drag area; fitting one speed can still produce a wrong traction requirement at another speed. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"在相同編組與天候下做不同速度的惰行分析，記錄風速方向與車頭迎角，避免把坡度造成的加速度誤判成空阻。 同步紀錄風向風速與地速，將穩速段牽引功率扣除可辨識的坡度和輔助負載。","textEn":"Compare coast-down observations across speeds with the same consist, log wind speed and direction, and separate gradient acceleration from aerodynamic resistance. Record wind vector and ground speed together, then remove identifiable gradient and auxiliary loads from steady-running traction power.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"對速度增加一成與阻力面積減少一成各算一次，對比功率節省，並把輪軌阻力另列以避免誇大整列節能比例。 再以本單元 v 的對照值重算 power，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate a ten percent speed increase and a ten percent drag-area reduction separately, compare power changes, and keep rolling resistance separate from whole-train energy savings. Also recalculate power for the alternative v value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「空氣阻力與牽引功率」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Aerodynamic drag and traction power\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","用平均電流代入平方損耗公式總能得到正確熱負荷","在相同編組與天候下做不同速度的惰行分析，記錄風速方向與車頭迎角，避免把坡度造成的加速度誤判成空阻。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Squaring average current always gives the correct resistive heat load.","Compare coast-down observations across speeds with the same consist, log wind speed and direction, and separate gradient acceleration from aerodynamic resistance."],"answer":2,"explanation":"在相同編組與天候下做不同速度的惰行分析，記錄風速方向與車頭迎角，避免把坡度造成的加速度誤判成空阻。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare coast-down observations across speeds with the same consist, log wind speed and direction, and separate gradient acceleration from aerodynamic resistance. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b310-v16-12","title":"空氣阻力與牽引功率：失效診斷","titleEn":"Aerodynamic drag and traction power: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-11"],"objective":"從症狀倒推「空氣阻力與牽引功率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Aerodynamic drag and traction power” and propose discriminating checks, corrective actions and prevention.","instruction":"車底設備改變或側風會改變有效阻力面積；若只以單一速度校準，仍可能在另一速度得到錯誤牽引需求。 需核對風向，避免把順風和逆風的相對速度互換。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Underbody changes and crosswinds alter effective drag area; fitting one speed can still produce a wrong traction requirement at another speed. Check wind direction to avoid reversing the relative-speed treatment of headwind and tailwind. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：評估空氣阻力的速度三次方功率變化，保留阻力係數假設。","observationEn":"Link to the mechanism: Evaluate cubic aerodynamic power growth while retaining the assumed drag coefficient.","failure":"誤判風險：若相信「速度增加一成時克服空氣阻力的功率只增加一成」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A ten percent speed increase raises aerodynamic power by only ten percent.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"車底設備改變或側風會改變有效阻力面積；若只以單一速度校準，仍可能在另一速度得到錯誤牽引需求。 需核對風向，避免把順風和逆風的相對速度互換。","textEn":"Underbody changes and crosswinds alter effective drag area; fitting one speed can still produce a wrong traction requirement at another speed. Check wind direction to avoid reversing the relative-speed treatment of headwind and tailwind.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「空氣阻力與牽引功率」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Aerodynamic drag and traction power\" shows distress, which diagnosis is most reasonable?","options":["車底設備改變或側風會改變有效阻力面積；若只以單一速度校準，仍可能在另一速度得到錯誤牽引需求。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","只要靜態接觸線高度正確就能保證高速受流品質"],"optionsEn":["Underbody changes and crosswinds alter effective drag area; fitting one speed can still produce a wrong traction requirement at another speed.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Correct static contact-wire height alone guarantees good current collection at high speed."],"answer":0,"explanation":"車底設備改變或側風會改變有效阻力面積；若只以單一速度校準，仍可能在另一速度得到錯誤牽引需求。 需以量測區分可能原因。","explanationEn":"Underbody changes and crosswinds alter effective drag area; fitting one speed can still produce a wrong traction requirement at another speed. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b310-v16-13","title":"接觸線張力波速：機制與系統路徑","titleEn":"Contact-wire tension wave speed: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-12"],"objective":"說明「接觸線張力波速」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Contact-wire tension wave speed” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。波速與列車速度的比值提供動態風險線索，但多跨懸掛、吊弦和接觸非線性不能由單根弦模型取代。 線密度決定單位長度的慣性，張力提供恢復作用，因此波速平方與張力成正比。提高張力也改變支承受力；波速裕度只能作篩檢，不能推定接觸力必然均勻。 把受電弓與接觸線看成互動系統，避免只提高張力求解。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「接觸線張力波速」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Pantograph disturbances propagate along the contact wire. Greater tension raises transverse wave speed, whereas greater mass per length lowers it. The ratio to train speed offers a dynamic clue, but multispan suspension, droppers and contact nonlinearity cannot be replaced by a single-string model. Linear density represents inertia per unit length and tension supplies restoring force, so squared wave speed scales with tension. Higher tension also changes support loading. A wave-speed margin is a screening measure, not proof of uniform contact force. Treat pantograph and contact wire as an interacting system rather than solving by tension increase alone. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Contact-wire tension wave speed” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：tension=20400 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=136.1817 m/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20400 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=136.1817 m/s.","failure":"常見誤解：「只要靜態接觸線高度正確就能保證高速受流品質」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Correct static contact-wire height alone guarantees good current collection at high speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「接觸線張力波速」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Contact-wire tension wave speed”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-13-k1","title":"接觸線張力波速","titleEn":"Contact-wire tension wave speed","text":"受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。波速與列車速度的比值提供動態風險線索，但多跨懸掛、吊弦和接觸非線性不能由單根弦模型取代。","textEn":"Pantograph disturbances propagate along the contact wire. Greater tension raises transverse wave speed, whereas greater mass per length lowers it.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要靜態接觸線高度正確就能保證高速受流品質 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Correct static contact-wire height alone guarantees good current collection at high speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「接觸線張力波速」，下列哪一項敘述正確？","questionEn":"Which statement about \"Contact-wire tension wave speed\" is correct?","options":["只要靜態接觸線高度正確就能保證高速受流品質","受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。","無電區長度改變不會影響列車離開時的速度"],"optionsEn":["Correct static contact-wire height alone guarantees good current collection at high speed.","Pantograph disturbances propagate along the contact wire.","Changing the length of an unpowered section cannot change exit speed."],"answer":1,"explanation":"受電弓擾動會沿接觸線傳播，張力提高使橫波速度上升而線密度增加使波速下降。 其餘選項是常見誤解。","explanationEn":"Pantograph disturbances propagate along the contact wire. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b310-v16-14","title":"接觸線張力波速：定量估算","titleEn":"Contact-wire tension wave speed: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-13"],"objective":"以數值模型估算「接觸線張力波速」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Contact-wire tension wave speed” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：tension=20400 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=136.1817 m/s。敏感度：tension 單獨增加百分之十至 22440 N，其餘固定，結果為 142.8286 m/s。模型邊界：無彎曲剛度的均勻張弦；不是受流合格判定或允許車速。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20400 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=136.1817 m/s. Sensitivity: tension, increase this input alone by ten percent, to 22440 N, with all other inputs fixed, gives 142.8286 m/s. Model boundary: Uniform tensioned string without bending stiffness; not a current-collection acceptance rule or permitted train speed. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。","observationEn":"How to cross-check: Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：tension=20400 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=136.1817 m/s。敏感度：tension 單獨增加百分之十至 22440 N，其餘固定，結果為 142.8286 m/s。模型邊界：無彎曲剛度的均勻張弦；不是受流合格判定或允許車速。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20400 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=136.1817 m/s. Sensitivity: tension, increase this input alone by ten percent, to 22440 N, with all other inputs fixed, gives 142.8286 m/s. Model boundary: Uniform tensioned string without bending stiffness; not a current-collection acceptance rule or permitted train speed.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「接觸線張力波速」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Contact-wire tension wave speed\", which statement holds?","options":["完全拘束的鋼軌升溫仍會無應力地自由伸長","快慢車平均速度不同也不會影響同線時刻表容量","原創假想算例，全部輸入均非本工程操作參數：tension=20400 N; density=1.1 kg/m。"],"optionsEn":["A fully restrained rail still expands freely without stress when heated.","Different fast and slow train speeds do not affect shared-line timetable capacity.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：tension=20400 N; density=1.1 kg/m；計算：wave_speed=(tension/density)**0.5=136.1817 m/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: tension=20400 N; density=1.1 kg/m; calculation: wave_speed=(tension/density)**0.5=136.1817 m/s. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b310-v16-15","title":"接觸線張力波速：試驗與驗證","titleEn":"Contact-wire tension wave speed: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「接觸線張力波速」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Contact-wire tension wave speed” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。 核對接觸線張力、單位長度質量及量測位置，並用接觸力和離線事件檢查動態品質。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks. Verify contact-wire tension, mass per unit length and measurement location, then examine contact force and loss-of-contact events for dynamic quality. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將張力降低一成和線密度增加一成分別計算波速，列出尚需哪些接觸力量測才能討論動態受流品質。 再以本單元 tension 的對照值重算 wave_speed，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Reduce tension and increase wire mass density separately by ten percent, calculate wave speed, and identify the contact-force measurements still needed to assess dynamic collection. Also recalculate wave_speed for the alternative tension value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。 核對接觸線張力、單位長度質量及量測位置，並用接觸力和離線事件檢查動態品質。","textEn":"Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks. Verify contact-wire tension, mass per unit length and measurement location, then examine contact force and loss-of-contact events for dynamic quality.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"將張力降低一成和線密度增加一成分別計算波速，列出尚需哪些接觸力量測才能討論動態受流品質。 再以本單元 tension 的對照值重算 wave_speed，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Reduce tension and increase wire mass density separately by ten percent, calculate wave speed, and identify the contact-force measurements still needed to assess dynamic collection. Also recalculate wave_speed for the alternative tension value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「接觸線張力波速」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Contact-wire tension wave speed\"?","options":["核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。","不確定度太難估計，報告中只寫最佳值即可。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks.","Uncertainty is too hard to estimate, so the report may state only the best value.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":0,"explanation":"核對補償裝置行程、線溫與張力紀錄，再量測受電弓接觸力統計及離線事件，辨別平均值正常但峰值異常。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check compensation travel, wire temperature and tension, then examine contact-force statistics and loss-of-contact events to distinguish acceptable means from abnormal peaks. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b310-v16-16","title":"接觸線張力波速：失效診斷","titleEn":"Contact-wire tension wave speed: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-15"],"objective":"從症狀倒推「接觸線張力波速」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Contact-wire tension wave speed” and propose discriminating checks, corrective actions and prevention.","instruction":"補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 波速符合估算仍可能離線，需查看接觸力的時間歷程。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. Agreement in wave-speed estimates does not rule out contact loss; inspect contact-force histories. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把受電弓與接觸線看成互動系統，避免只提高張力求解。","observationEn":"Link to the mechanism: Treat pantograph and contact wire as an interacting system rather than solving by tension increase alone.","failure":"誤判風險：若相信「只要靜態接觸線高度正確就能保證高速受流品質」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Correct static contact-wire height alone guarantees good current collection at high speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 波速符合估算仍可能離線，需查看接觸力的時間歷程。","textEn":"A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. Agreement in wave-speed estimates does not rule out contact loss; inspect contact-force histories.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「接觸線張力波速」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Contact-wire tension wave speed\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。","無電區長度改變不會影響列車離開時的速度"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness.","Changing the length of an unpowered section cannot change exit speed."],"answer":1,"explanation":"補償裝置卡滯會讓溫度變化改變張力，吊弦鬆弛又會改變局部動態剛度；只讀取靜態高度難以辨識。 需以量測區分可能原因。","explanationEn":"A sticking tensioning device lets temperature change tension, while slack droppers change local dynamic stiffness; static wire height alone cannot identify either mechanism. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b310-v16-s3","title":"無電區惰行與速度損失與速度限制轉換與預告距離","titleEn":"Coasting through an unpowered section & Speed-limit transition and warning distance","description":"本階段聚焦「無電區惰行與速度損失」與「速度限制轉換與預告距離」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Coasting through an unpowered section\" and \"Speed-limit transition and warning distance\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b310-v16-17","title":"無電區惰行與速度損失：機制與系統路徑","titleEn":"Coasting through an unpowered section: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-16"],"objective":"說明「無電區惰行與速度損失」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Coasting through an unpowered section” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"列車通過無電區時需依靠動能克服阻力，簡化恆阻力模型把阻力做功從初始動能扣除。區段長度、初速與坡度決定剩餘速度，供電切換邏輯和防誤合閘仍需獨立驗證。 無牽引不等於無運動，列車以動能克服所宣告的阻力。若距離超過此阻力下的可滑行距離，平方根將無實數解，表示通過情境不成立而非計算器錯誤。 在分相區設計無牽引滑行的初末速度與時間驗算。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「無電區惰行與速度損失」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A train coasting through an unpowered section uses kinetic energy to overcome resistance. A constant-resistance model subtracts work from initial kinetic energy. Length, entry speed and gradient determine remaining speed, while switching logic and prevention of inappropriate re-energisation require separate verification. No traction does not mean no motion: kinetic energy overcomes the declared resistance. If the section exceeds the available coasting distance, the square root has no real solution, indicating an infeasible passage case rather than a calculator malfunction. Check entry speed, exit speed and coasting time through an unpowered neutral section. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Coasting through an unpowered section” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：v=50 m/s; force=15300 N; length=500 m; mass=250000 kg；計算：exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=50 m/s; force=15300 N; length=500 m; mass=250000 kg; calculation: exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s.","failure":"常見誤解：「無電區長度改變不會影響列車離開時的速度」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Changing the length of an unpowered section cannot change exit speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「無電區惰行與速度損失」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Coasting through an unpowered section”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-17-k1","title":"無電區惰行與速度損失","titleEn":"Coasting through an unpowered section","text":"列車通過無電區時需依靠動能克服阻力，簡化恆阻力模型把阻力做功從初始動能扣除。區段長度、初速與坡度決定剩餘速度，供電切換邏輯和防誤合閘仍需獨立驗證。","textEn":"A train coasting through an unpowered section uses kinetic energy to overcome resistance. A constant-resistance model subtracts work from initial kinetic energy.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：無電區長度改變不會影響列車離開時的速度 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Changing the length of an unpowered section cannot change exit speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「無電區惰行與速度損失」，下列哪一項敘述正確？","questionEn":"Which statement about \"Coasting through an unpowered section\" is correct?","options":["無電區長度改變不會影響列車離開時的速度","降低目標速度時可忽略初速與目標速度的平方差","列車通過無電區時需依靠動能克服阻力，簡化恆阻力模型把阻力做功從初始動能扣除。"],"optionsEn":["Changing the length of an unpowered section cannot change exit speed.","Reducing target speed allows the squared-speed difference to be ignored.","A train coasting through an unpowered section uses kinetic energy to overcome resistance."],"answer":2,"explanation":"列車通過無電區時需依靠動能克服阻力，簡化恆阻力模型把阻力做功從初始動能扣除。 其餘選項是常見誤解。","explanationEn":"A train coasting through an unpowered section uses kinetic energy to overcome resistance. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b310-v16-18","title":"無電區惰行與速度損失：定量估算","titleEn":"Coasting through an unpowered section: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-17"],"objective":"以數值模型估算「無電區惰行與速度損失」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Coasting through an unpowered section” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：v=50 m/s; force=15300 N; length=500 m; mass=250000 kg；計算：exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s。敏感度：force 單獨增加百分之十至 16830 N，其餘固定，結果為 49.32221 m/s。模型邊界：水平路線且恆阻力，根號內必須非負；不含低速停車及切換暫態。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: v=50 m/s; force=15300 N; length=500 m; mass=250000 kg; calculation: exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s. Sensitivity: force, increase this input alone by ten percent, to 16830 N, with all other inputs fixed, gives 49.32221 m/s. Model boundary: Level track and constant resistance with a nonnegative radicand; stopping within the section and switching transients are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同步記錄受電電壓、主斷路器狀態和列車速度，確認無電區邊界與里程一致，再核對惰行能量差。","observationEn":"How to cross-check: Synchronise line voltage, main-breaker status and speed, align electrical boundaries with distance coordinates, and check the coasting energy difference.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：v=50 m/s; force=15300 N; length=500 m; mass=250000 kg；計算：exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s。敏感度：force 單獨增加百分之十至 16830 N，其餘固定，結果為 49.32221 m/s。模型邊界：水平路線且恆阻力，根號內必須非負；不含低速停車及切換暫態。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=50 m/s; force=15300 N; length=500 m; mass=250000 kg; calculation: exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s. Sensitivity: force, increase this input alone by ten percent, to 16830 N, with all other inputs fixed, gives 49.32221 m/s. Model boundary: Level track and constant resistance with a nonnegative radicand; stopping within the section and switching transients are excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「無電區惰行與速度損失」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Coasting through an unpowered section\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：v=50 m/s; force=15300 N; length=500 m; mass=250000 kg。","疲勞損傷只取決於通過列車總數而不受應力幅影響","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Original hypothetical exercise.","Fatigue damage depends only on train count and is independent of stress range.","Squaring average current always gives the correct resistive heat load."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：v=50 m/s; force=15300 N; length=500 m; mass=250000 kg；計算：exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: v=50 m/s; force=15300 N; length=500 m; mass=250000 kg; calculation: exit_speed=(v*v-2*force*length/mass)**0.5=49.38421 m/s. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b310-v16-19","title":"無電區惰行與速度損失：試驗與驗證","titleEn":"Coasting through an unpowered section: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「無電區惰行與速度損失」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Coasting through an unpowered section” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同步記錄受電電壓、主斷路器狀態和列車速度，確認無電區邊界與里程一致，再核對惰行能量差。 以入口和出口獨立速度對照滑行距離，核對斷電區時間戳及坡度是否被模型排除。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Synchronise line voltage, main-breaker status and speed, align electrical boundaries with distance coordinates, and check the coasting energy difference. Compare independently measured entry and exit speeds with coasting distance, checking power-off timestamps and whether gradient is excluded. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：在相同初速下增加區段長度，檢查能量是否足夠通過，再列出電氣切換與機械惰行模型各自需要的驗證資料。 再以本單元 force 的對照值重算 exit_speed，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase section length at fixed entry speed, test whether energy remains sufficient, and list separate evidence for electrical switching and mechanical coasting models. Also recalculate exit_speed for the alternative force value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：邊界定位誤差可能使主斷路器切換時機錯誤；把坡度阻力遺漏會低估上坡無電區的速度下降。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Boundary-position error can mistime breaker switching; omitting gradient resistance understates speed loss in an uphill unpowered section. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"同步記錄受電電壓、主斷路器狀態和列車速度，確認無電區邊界與里程一致，再核對惰行能量差。 以入口和出口獨立速度對照滑行距離，核對斷電區時間戳及坡度是否被模型排除。","textEn":"Synchronise line voltage, main-breaker status and speed, align electrical boundaries with distance coordinates, and check the coasting energy difference. Compare independently measured entry and exit speeds with coasting distance, checking power-off timestamps and whether gradient is excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"在相同初速下增加區段長度，檢查能量是否足夠通過，再列出電氣切換與機械惰行模型各自需要的驗證資料。 再以本單元 force 的對照值重算 exit_speed，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase section length at fixed entry speed, test whether energy remains sufficient, and list separate evidence for electrical switching and mechanical coasting models. Also recalculate exit_speed for the alternative force value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「無電區惰行與速度損失」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Coasting through an unpowered section\"?","options":["允收準則可以等看到量測數據後再決定。","同步記錄受電電壓、主斷路器狀態和列車速度，確認無電區邊界與里程一致，再核對惰行能量差。","長下坡只需通過一次緊急停車試驗就能驗證持續制動"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Synchronise line voltage, main-breaker status and speed, align electrical boundaries with distance coordinates, and check the coasting energy difference.","One emergency stop test verifies continuous braking capability on a long descent."],"answer":1,"explanation":"同步記錄受電電壓、主斷路器狀態和列車速度，確認無電區邊界與里程一致，再核對惰行能量差。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Synchronise line voltage, main-breaker status and speed, align electrical boundaries with distance coordinates, and check the coasting energy difference. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b310-v16-20","title":"無電區惰行與速度損失：失效診斷","titleEn":"Coasting through an unpowered section: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-19"],"objective":"從症狀倒推「無電區惰行與速度損失」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Coasting through an unpowered section” and propose discriminating checks, corrective actions and prevention.","instruction":"邊界定位誤差可能使主斷路器切換時機錯誤；把坡度阻力遺漏會低估上坡無電區的速度下降。 若計算顯示無法通過，不能把負根號截成零後繼續排程。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Boundary-position error can mistime breaker switching; omitting gradient resistance understates speed loss in an uphill unpowered section. If passage is infeasible, do not clamp a negative radicand to zero and continue scheduling. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在分相區設計無牽引滑行的初末速度與時間驗算。","observationEn":"Link to the mechanism: Check entry speed, exit speed and coasting time through an unpowered neutral section.","failure":"誤判風險：若相信「無電區長度改變不會影響列車離開時的速度」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Changing the length of an unpowered section cannot change exit speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"邊界定位誤差可能使主斷路器切換時機錯誤；把坡度阻力遺漏會低估上坡無電區的速度下降。 若計算顯示無法通過，不能把負根號截成零後繼續排程。","textEn":"Boundary-position error can mistime breaker switching; omitting gradient resistance understates speed loss in an uphill unpowered section. If passage is infeasible, do not clamp a negative radicand to zero and continue scheduling.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「無電區惰行與速度損失」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Coasting through an unpowered section\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","降低目標速度時可忽略初速與目標速度的平方差","邊界定位誤差可能使主斷路器切換時機錯誤；把坡度阻力遺漏會低估上坡無電區的速度下降。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Reducing target speed allows the squared-speed difference to be ignored.","Boundary-position error can mistime breaker switching; omitting gradient resistance understates speed loss in an uphill unpowered section."],"answer":2,"explanation":"邊界定位誤差可能使主斷路器切換時機錯誤；把坡度阻力遺漏會低估上坡無電區的速度下降。 需以量測區分可能原因。","explanationEn":"Boundary-position error can mistime breaker switching; omitting gradient resistance understates speed loss in an uphill unpowered section. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b310-v16-21","title":"速度限制轉換與預告距離：機制與系統路徑","titleEn":"Speed-limit transition and warning distance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-20"],"objective":"說明「速度限制轉換與預告距離」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Speed-limit transition and warning distance” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。此處用明示減速度得到教學距離，真正保護曲線還需加入定位誤差、坡度、制動建立及車輛差異。 目標速度不一定是零，進入較低速區也需要保護距離。計算使用同一距離基準與速度單位，並把定位誤差和延遲裕度分開，才能避免重複或漏加安全邊界。 對高速線轉入低速區的目標速度建立監督距離。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「速度限制轉換與預告距離」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy. The expression contains the difference of squared initial and target speeds. A teaching deceleration gives one distance; a real protection curve additionally needs position uncertainty, gradient, brake build-up and vehicle variation. The target speed need not be zero: entry into a lower-speed section also requires protection distance. Use one distance reference and consistent speed units. Keep localisation uncertainty and delay margins separate to prevent duplicated or omitted boundaries. Construct supervision distance for a transition from high-speed running to a lower target speed. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Speed-limit transition and warning distance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=2690.738 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=2690.738 m.","failure":"常見誤解：「降低目標速度時可忽略初速與目標速度的平方差」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Reducing target speed allows the squared-speed difference to be ignored.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「速度限制轉換與預告距離」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Speed-limit transition and warning distance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-21-k1","title":"速度限制轉換與預告距離","titleEn":"Speed-limit transition and warning distance","text":"進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。此處用明示減速度得到教學距離，真正保護曲線還需加入定位誤差、坡度、制動建立及車輛差異。","textEn":"Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy. The expression contains the difference of squared initial and target speeds.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：降低目標速度時可忽略初速與目標速度的平方差 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Reducing target speed allows the squared-speed difference to be ignored. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「速度限制轉換與預告距離」，下列哪一項敘述正確？","questionEn":"Which statement about \"Speed-limit transition and warning distance\" is correct?","options":["進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。","降低目標速度時可忽略初速與目標速度的平方差","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy.","Reducing target speed allows the squared-speed difference to be ignored.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。 其餘選項是常見誤解。","explanationEn":"Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b310-v16-22","title":"速度限制轉換與預告距離：定量估算","titleEn":"Speed-limit transition and warning distance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-21"],"objective":"以數值模型估算「速度限制轉換與預告距離」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Speed-limit transition and warning distance” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=2690.738 m。敏感度：initial 單獨增加百分之十至 78.54 m/s，其餘固定，結果為 3514.255 m。模型邊界：初速大於目標速度且定減速度；沒有通訊延遲與安全裕度。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=2690.738 m. Sensitivity: initial, increase this input alone by ten percent, to 78.54 m/s, with all other inputs fixed, gives 3514.255 m. Model boundary: Initial speed above target and constant deceleration; communication delay and safety margins are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。","observationEn":"How to cross-check: Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=2690.738 m。敏感度：initial 單獨增加百分之十至 78.54 m/s，其餘固定，結果為 3514.255 m。模型邊界：初速大於目標速度且定減速度；沒有通訊延遲與安全裕度。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=2690.738 m. Sensitivity: initial, increase this input alone by ten percent, to 78.54 m/s, with all other inputs fixed, gives 3514.255 m. Model boundary: Initial speed above target and constant deceleration; communication delay and safety margins are excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「速度限制轉換與預告距離」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Speed-limit transition and warning distance\", which statement holds?","options":["快慢車平均速度不同也不會影響同線時刻表容量","原創假想算例，全部輸入均非本工程操作參數：initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["Different fast and slow train speeds do not affect shared-line timetable capacity.","Original hypothetical exercise.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=2690.738 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=71.4 m/s; target=40 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=2690.738 m. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b310-v16-23","title":"速度限制轉換與預告距離：試驗與驗證","titleEn":"Speed-limit transition and warning distance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「速度限制轉換與預告距離」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Speed-limit transition and warning distance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。 以已知初速與目標速度重播控制資料，核對速度單位、里程方向及列車前端參考位置。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope. Replay control data at known initial and target speeds, checking speed units, chainage direction and the reference position of the train front. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對同一初速設定兩個目標速度，重算轉換距離，畫出能量差並說明為何不能按速度差線性縮放距離。 再以本單元 initial 的對照值重算 transition，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Use two target speeds at one initial speed, recalculate transition distance, plot the energy differences, and explain why distance cannot scale linearly with the speed difference. Also recalculate transition for the alternative initial value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。 以已知初速與目標速度重播控制資料，核對速度單位、里程方向及列車前端參考位置。","textEn":"Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope. Replay control data at known initial and target speeds, checking speed units, chainage direction and the reference position of the train front.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"對同一初速設定兩個目標速度，重算轉換距離，畫出能量差並說明為何不能按速度差線性縮放距離。 再以本單元 initial 的對照值重算 transition，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Use two target speeds at one initial speed, recalculate transition distance, plot the energy differences, and explain why distance cannot scale linearly with the speed difference. Also recalculate transition for the alternative initial value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「速度限制轉換與預告距離」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Speed-limit transition and warning distance\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","速度增加一成時克服空氣阻力的功率只增加一成","重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","A ten percent speed increase raises aerodynamic power by only ten percent.","Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope."],"answer":2,"explanation":"重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b310-v16-24","title":"速度限制轉換與預告距離：失效診斷","titleEn":"Speed-limit transition and warning distance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-23"],"objective":"從症狀倒推「速度限制轉換與預告距離」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Speed-limit transition and warning distance” and propose discriminating checks, corrective actions and prevention.","instruction":"限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 若目標速度高於初速，此減速模型的工況設定便不成立。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. If target speed exceeds initial speed, the stated deceleration case no longer applies. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：對高速線轉入低速區的目標速度建立監督距離。","observationEn":"Link to the mechanism: Construct supervision distance for a transition from high-speed running to a lower target speed.","failure":"誤判風險：若相信「降低目標速度時可忽略初速與目標速度的平方差」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Reducing target speed allows the squared-speed difference to be ignored.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 若目標速度高於初速，此減速模型的工況設定便不成立。","textEn":"A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. If target speed exceeds initial speed, the stated deceleration case no longer applies.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「速度限制轉換與預告距離」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Speed-limit transition and warning distance\" shows distress, which diagnosis is most reasonable?","options":["限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。","只要結構還沒倒，就代表安全餘裕仍然足夠。","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion.","As long as the structure is still standing, its safety margin must still be adequate.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 需以量測區分可能原因。","explanationEn":"A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b310-v16-s4","title":"長軌溫升與受限熱應力與重複荷載與線性損傷帳","titleEn":"Long-rail temperature and restrained stress & Repeated loading and linear damage account","description":"本階段聚焦「長軌溫升與受限熱應力」與「重複荷載與線性損傷帳」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Long-rail temperature and restrained stress\" and \"Repeated loading and linear damage account\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b310-v16-25","title":"長軌溫升與受限熱應力：機制與系統路徑","titleEn":"Long-rail temperature and restrained stress: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-24"],"objective":"說明「長軌溫升與受限熱應力」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Long-rail temperature and restrained stress” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。鎖定軌溫決定應力零點而空氣溫度不等於鋼軌溫度；實際扣件滑移與軌道側向阻力還會改變穩定問題。 溫差應相對於鋼軌實際無應力狀態，而非任意室溫。完全拘束估算給出軸向應力尺度；當扣件滑移或軌道彎曲出現時，需要位移相容和側向穩定分析。 比較線形改建前後鎖定軌溫與拘束條件的紀錄要求。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「長軌溫升與受限熱應力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. Stress-free rail temperature defines the reference and differs from air temperature. Fastener slip and lateral track resistance additionally govern stability, beyond the one-dimensional thermal-stress estimate. Temperature change must reference the rail’s actual stress-free state, not an arbitrary room temperature. Full restraint gives an axial stress scale. Fastener slip or track curvature requires displacement compatibility and lateral stability analysis beyond this expression. Compare documentation of stress-free temperature and restraint before and after alignment work. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Long-rail temperature and restrained stress” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K；計算：compression=E*alpha*deltaT=73.899 MPa。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K; calculation: compression=E*alpha*deltaT=73.899 MPa.","failure":"常見誤解：「完全拘束的鋼軌升溫仍會無應力地自由伸長」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A fully restrained rail still expands freely without stress when heated.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「長軌溫升與受限熱應力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Long-rail temperature and restrained stress”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-25-k1","title":"長軌溫升與受限熱應力","titleEn":"Long-rail temperature and restrained stress","text":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。鎖定軌溫決定應力零點而空氣溫度不等於鋼軌溫度；實際扣件滑移與軌道側向阻力還會改變穩定問題。","textEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. Stress-free rail temperature defines the reference and differs from air temperature.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：完全拘束的鋼軌升溫仍會無應力地自由伸長 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A fully restrained rail still expands freely without stress when heated. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「長軌溫升與受限熱應力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Long-rail temperature and restrained stress\" is correct?","options":["完全拘束的鋼軌升溫仍會無應力地自由伸長","自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。","疲勞損傷只取決於通過列車總數而不受應力幅影響"],"optionsEn":["A fully restrained rail still expands freely without stress when heated.","A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression.","Fatigue damage depends only on train count and is independent of stress range."],"answer":1,"explanation":"自由鋼軌升溫會伸長，完全拘束的理想鋼軌則把熱應變轉成壓應力。 其餘選項是常見誤解。","explanationEn":"A free rail expands on heating, while an ideally restrained rail converts thermal strain into compression. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b310-v16-26","title":"長軌溫升與受限熱應力：定量估算","titleEn":"Long-rail temperature and restrained stress: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-25"],"objective":"以數值模型估算「長軌溫升與受限熱應力」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Long-rail temperature and restrained stress” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K；計算：compression=E*alpha*deltaT=73.899 MPa。敏感度：deltaT 單獨增加百分之十至 33.66 K，其餘固定，結果為 81.2889 MPa。模型邊界：完全軸向拘束與線彈性；不計挫曲、初彎、殘留應力及塑性。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K; calculation: compression=E*alpha*deltaT=73.899 MPa. Sensitivity: deltaT, increase this input alone by ten percent, to 33.66 K, with all other inputs fixed, gives 81.2889 MPa. Model boundary: Full axial restraint and linear elasticity; buckling, initial curvature, residual stress and plasticity are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。","observationEn":"How to cross-check: Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K；計算：compression=E*alpha*deltaT=73.899 MPa。敏感度：deltaT 單獨增加百分之十至 33.66 K，其餘固定，結果為 81.2889 MPa。模型邊界：完全軸向拘束與線彈性；不計挫曲、初彎、殘留應力及塑性。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K; calculation: compression=E*alpha*deltaT=73.899 MPa. Sensitivity: deltaT, increase this input alone by ten percent, to 33.66 K, with all other inputs fixed, gives 81.2889 MPa. Model boundary: Full axial restraint and linear elasticity; buckling, initial curvature, residual stress and plasticity are excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「長軌溫升與受限熱應力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Long-rail temperature and restrained stress\", which statement holds?","options":["用平均電流代入平方損耗公式總能得到正確熱負荷","長下坡只需通過一次緊急停車試驗就能驗證持續制動","原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K。"],"optionsEn":["Squaring average current always gives the correct resistive heat load.","One emergency stop test verifies continuous braking capability on a long descent.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K；計算：compression=E*alpha*deltaT=73.899 MPa。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: E=210000 MPa; alpha=1.15e-05 1/K; deltaT=30.6 K; calculation: compression=E*alpha*deltaT=73.899 MPa. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b310-v16-27","title":"長軌溫升與受限熱應力：試驗與驗證","titleEn":"Long-rail temperature and restrained stress: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「長軌溫升與受限熱應力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Long-rail temperature and restrained stress” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 以鋼軌接觸式溫度計校驗遙測值，核對應變零點，並保留日夜循環的升降溫路徑。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Calibrate remote readings against a contact rail thermometer, verify strain zero, and retain heating and cooling paths across the daily cycle. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：畫出自由、部分拘束與完全拘束三種邊界，重算熱變形或應力，標明哪些輸入必須由鋼軌溫度及扣件試驗取得。 再以本單元 deltaT 的對照值重算 compression，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Draw free, partial and full restraint boundaries, recalculate expansion or stress, and identify inputs requiring rail-temperature measurements and fastener tests. Also recalculate compression for the alternative deltaT value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 以鋼軌接觸式溫度計校驗遙測值，核對應變零點，並保留日夜循環的升降溫路徑。","textEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Calibrate remote readings against a contact rail thermometer, verify strain zero, and retain heating and cooling paths across the daily cycle.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"畫出自由、部分拘束與完全拘束三種邊界，重算熱變形或應力，標明哪些輸入必須由鋼軌溫度及扣件試驗取得。 再以本單元 deltaT 的對照值重算 compression，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Draw free, partial and full restraint boundaries, recalculate expansion or stress, and identify inputs requiring rail-temperature measurements and fastener tests. Also recalculate compression for the alternative deltaT value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「長軌溫升與受限熱應力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Long-rail temperature and restrained stress\"?","options":["量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","只要靜態接觸線高度正確就能保證高速受流品質"],"optionsEn":["Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","Correct static contact-wire height alone guarantees good current collection at high speed."],"answer":0,"explanation":"量鋼軌本體溫度與縱向應變，記錄鎖定狀態和扣件維修歷程，用不同位置感測器區分局部溫差與整段受限變形。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure rail temperature and longitudinal strain, record the fastening and maintenance history, and use spatially separated sensors to distinguish local heating from restrained segment behaviour. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b310-v16-28","title":"長軌溫升與受限熱應力：失效診斷","titleEn":"Long-rail temperature and restrained stress: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-27"],"objective":"從症狀倒推「長軌溫升與受限熱應力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Long-rail temperature and restrained stress” and propose discriminating checks, corrective actions and prevention.","instruction":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需查鎖定軌溫紀錄，不能以當天最低氣溫當無應力點。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Check stress-free-temperature records rather than using the day’s minimum air temperature as the reference. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較線形改建前後鎖定軌溫與拘束條件的紀錄要求。","observationEn":"Link to the mechanism: Compare documentation of stress-free temperature and restraint before and after alignment work.","failure":"誤判風險：若相信「完全拘束的鋼軌升溫仍會無應力地自由伸長」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A fully restrained rail still expands freely without stress when heated.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需查鎖定軌溫紀錄，不能以當天最低氣溫當無應力點。","textEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Check stress-free-temperature records rather than using the day’s minimum air temperature as the reference.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「長軌溫升與受限熱應力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Long-rail temperature and restrained stress\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。","疲勞損傷只取決於通過列車總數而不受應力幅影響"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Substituting air temperature misstates thermal loading.","Fatigue damage depends only on train count and is independent of stress range."],"answer":1,"explanation":"把氣溫直接當成鋼軌溫度會錯估熱荷載；扣件鬆動可能降低局部軸力卻增加位移，不能據此宣稱整體穩定性改善。 需以量測區分可能原因。","explanationEn":"Substituting air temperature misstates thermal loading; loose fasteners may reduce local force while increasing displacement, which does not prove improved overall stability. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b310-v16-29","title":"重複荷載與線性損傷帳：機制與系統路徑","titleEn":"Repeated loading and linear damage account: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-28"],"objective":"說明「重複荷載與線性損傷帳」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Repeated loading and linear damage account” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"疲勞取決於應力範圍與循環次數，線性累積把各級循環數除以對應壽命後相加。此帳務能比較荷載譜，卻忽略順序效應、腐蝕與裂紋成長，損傷和為一不是對任何構件的通用失效保證。 線性累積損傷不保留載重順序，也不能自行描述腐蝕、裂紋閉合和超載效應。疲勞曲線的適用材料與應力定義必須一致，否則算出的壽命比例沒有可比性。 將多年通過列車造成的循環分成應力幅級距。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「重複荷載與線性損傷帳」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Fatigue depends on stress range and cycle count. Linear accumulation sums the fraction of life consumed at each level. This accounting compares load spectra but omits sequence effects, corrosion and crack growth; a sum of one is not a universal failure guarantee for every component. Linear cumulative damage does not retain load order and cannot independently describe corrosion, crack closure or overload effects. The fatigue curve must match the material and stress definition; otherwise calculated life fractions are not comparable. Group repeated train passages into stress-range bins for cumulative-damage discussion. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Repeated loading and linear damage account” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles；計算：damage_index=n1/N1+n2/N2=0.404 1。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles; calculation: damage_index=n1/N1+n2/N2=0.404 1.","failure":"常見誤解：「疲勞損傷只取決於通過列車總數而不受應力幅影響」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Fatigue damage depends only on train count and is independent of stress range.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「重複荷載與線性損傷帳」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Repeated loading and linear damage account”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-29-k1","title":"重複荷載與線性損傷帳","titleEn":"Repeated loading and linear damage account","text":"疲勞取決於應力範圍與循環次數，線性累積把各級循環數除以對應壽命後相加。此帳務能比較荷載譜，卻忽略順序效應、腐蝕與裂紋成長，損傷和為一不是對任何構件的通用失效保證。","textEn":"Fatigue depends on stress range and cycle count. Linear accumulation sums the fraction of life consumed at each level.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：疲勞損傷只取決於通過列車總數而不受應力幅影響 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Fatigue damage depends only on train count and is independent of stress range. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「重複荷載與線性損傷帳」，下列哪一項敘述正確？","questionEn":"Which statement about \"Repeated loading and linear damage account\" is correct?","options":["疲勞損傷只取決於通過列車總數而不受應力幅影響","快慢車平均速度不同也不會影響同線時刻表容量","疲勞取決於應力範圍與循環次數，線性累積把各級循環數除以對應壽命後相加。"],"optionsEn":["Fatigue damage depends only on train count and is independent of stress range.","Different fast and slow train speeds do not affect shared-line timetable capacity.","Fatigue depends on stress range and cycle count."],"answer":2,"explanation":"疲勞取決於應力範圍與循環次數，線性累積把各級循環數除以對應壽命後相加。 其餘選項是常見誤解。","explanationEn":"Fatigue depends on stress range and cycle count. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b310-v16-30","title":"重複荷載與線性損傷帳：定量估算","titleEn":"Repeated loading and linear damage account: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-29"],"objective":"以數值模型估算「重複荷載與線性損傷帳」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Repeated loading and linear damage account” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles；計算：damage_index=n1/N1+n2/N2=0.404 1。敏感度：n1 將整數計數增加到 224401至 224401 cycles，其餘固定，結果為 0.424401 1。模型邊界：兩級循環的Miner帳務且壽命輸入已假設；不外推真實剩餘壽命。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles; calculation: damage_index=n1/N1+n2/N2=0.404 1. Sensitivity: n1, increase the integer count to 224401, to 224401 cycles, with all other inputs fixed, gives 0.424401 1. Model boundary: Two-level Miner accounting with assumed life values; no real residual-life prediction is made. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以雨流計數整理應變歷程，核對儀器零漂與列車通過事件，保留應力轉換和材料曲線的來源與適用範圍。","observationEn":"How to cross-check: Count strain histories using rainflow analysis, check sensor drift against train passages, and retain the source and applicability of stress conversion and material curves.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles；計算：damage_index=n1/N1+n2/N2=0.404 1。敏感度：n1 將整數計數增加到 224401至 224401 cycles，其餘固定，結果為 0.424401 1。模型邊界：兩級循環的Miner帳務且壽命輸入已假設；不外推真實剩餘壽命。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles; calculation: damage_index=n1/N1+n2/N2=0.404 1. Sensitivity: n1, increase the integer count to 224401, to 224401 cycles, with all other inputs fixed, gives 0.424401 1. Model boundary: Two-level Miner accounting with assumed life values; no real residual-life prediction is made.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「重複荷載與線性損傷帳」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Repeated loading and linear damage account\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles。","任何速度下增加超高都一定減少車內橫向加速度","速度增加一成時克服空氣阻力的功率只增加一成"],"optionsEn":["Original hypothetical exercise.","Increasing cant always reduces lateral acceleration at every operating speed.","A ten percent speed increase raises aerodynamic power by only ten percent."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles；計算：damage_index=n1/N1+n2/N2=0.404 1。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: n1=204000 cycles; N1=1000000 cycles; n2=50000 cycles; N2=250000 cycles; calculation: damage_index=n1/N1+n2/N2=0.404 1. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b310-v16-31","title":"重複荷載與線性損傷帳：試驗與驗證","titleEn":"Repeated loading and linear damage account: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「重複荷載與線性損傷帳」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Repeated loading and linear damage account” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以雨流計數整理應變歷程，核對儀器零漂與列車通過事件，保留應力轉換和材料曲線的來源與適用範圍。 從原始應變檢查應力換算與循環計數，核對各級距的次數總和及疲勞曲線來源。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Count strain histories using rainflow analysis, check sensor drift against train passages, and retain the source and applicability of stress conversion and material curves. Check stress conversion and cycle counting from raw strain, verifying total counts across bins and the source of the fatigue curve. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保持總循環數不變，將部分低應力循環移到高應力級，重算損傷帳並說明需要何種檢測來支持剩餘壽命判讀。 再以本單元 n1 的對照值重算 damage_index，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Keep total cycles fixed while moving some cycles to the higher-stress level, recalculate damage, and identify inspections needed to support any remaining-life interpretation. Also recalculate damage_index for the alternative n1 value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：漏記少量大應力循環可能比漏記大量小循環更嚴重；焊趾局部應力也不能直接由遠處名義應變代表。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Missing a few large cycles can matter more than missing many small ones; nominal strain away from a weld cannot directly represent local weld-toe stress. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"以雨流計數整理應變歷程，核對儀器零漂與列車通過事件，保留應力轉換和材料曲線的來源與適用範圍。 從原始應變檢查應力換算與循環計數，核對各級距的次數總和及疲勞曲線來源。","textEn":"Count strain histories using rainflow analysis, check sensor drift against train passages, and retain the source and applicability of stress conversion and material curves. Check stress conversion and cycle counting from raw strain, verifying total counts across bins and the source of the fatigue curve.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"保持總循環數不變，將部分低應力循環移到高應力級，重算損傷帳並說明需要何種檢測來支持剩餘壽命判讀。 再以本單元 n1 的對照值重算 damage_index，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Keep total cycles fixed while moving some cycles to the higher-stress level, recalculate damage, and identify inspections needed to support any remaining-life interpretation. Also recalculate damage_index for the alternative n1 value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「重複荷載與線性損傷帳」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Repeated loading and linear damage account\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","以雨流計數整理應變歷程，核對儀器零漂與列車通過事件，保留應力轉換和材料曲線的來源與適用範圍。","無電區長度改變不會影響列車離開時的速度"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Count strain histories using rainflow analysis, check sensor drift against train passages, and retain the source and applicability of stress conversion and material curves.","Changing the length of an unpowered section cannot change exit speed."],"answer":1,"explanation":"以雨流計數整理應變歷程，核對儀器零漂與列車通過事件，保留應力轉換和材料曲線的來源與適用範圍。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Count strain histories using rainflow analysis, check sensor drift against train passages, and retain the source and applicability of stress conversion and material curves. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b310-v16-32","title":"重複荷載與線性損傷帳：失效診斷","titleEn":"Repeated loading and linear damage account: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-31"],"objective":"從症狀倒推「重複荷載與線性損傷帳」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Repeated loading and linear damage account” and propose discriminating checks, corrective actions and prevention.","instruction":"漏記少量大應力循環可能比漏記大量小循環更嚴重；焊趾局部應力也不能直接由遠處名義應變代表。 若應力級距漏計，累積損傷偏低不能證明構件仍完好。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Missing a few large cycles can matter more than missing many small ones; nominal strain away from a weld cannot directly represent local weld-toe stress. Understated damage caused by omitted stress bins is not evidence that the component remains sound. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將多年通過列車造成的循環分成應力幅級距。","observationEn":"Link to the mechanism: Group repeated train passages into stress-range bins for cumulative-damage discussion.","failure":"誤判風險：若相信「疲勞損傷只取決於通過列車總數而不受應力幅影響」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Fatigue damage depends only on train count and is independent of stress range.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"漏記少量大應力循環可能比漏記大量小循環更嚴重；焊趾局部應力也不能直接由遠處名義應變代表。 若應力級距漏計，累積損傷偏低不能證明構件仍完好。","textEn":"Missing a few large cycles can matter more than missing many small ones; nominal strain away from a weld cannot directly represent local weld-toe stress. Understated damage caused by omitted stress bins is not evidence that the component remains sound.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「重複荷載與線性損傷帳」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Repeated loading and linear damage account\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","快慢車平均速度不同也不會影響同線時刻表容量","漏記少量大應力循環可能比漏記大量小循環更嚴重；焊趾局部應力也不能直接由遠處名義應變代表。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Different fast and slow train speeds do not affect shared-line timetable capacity.","Missing a few large cycles can matter more than missing many small ones; nominal strain away from a weld cannot directly represent local weld-toe stress."],"answer":2,"explanation":"漏記少量大應力循環可能比漏記大量小循環更嚴重；焊趾局部應力也不能直接由遠處名義應變代表。 需以量測區分可能原因。","explanationEn":"Missing a few large cycles can matter more than missing many small ones; nominal strain away from a weld cannot directly represent local weld-toe stress. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b310-v16-s5","title":"快慢車追及與待避與電流平方損耗與散熱","titleEn":"Fast-slow train catch-up & Current-squared losses and cooling","description":"本階段聚焦「快慢車追及與待避」與「電流平方損耗與散熱」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Fast-slow train catch-up\" and \"Current-squared losses and cooling\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b310-v16-33","title":"快慢車追及與待避：機制與系統路徑","titleEn":"Fast-slow train catch-up: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-32"],"objective":"說明「快慢車追及與待避」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Fast-slow train catch-up” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"快車在同一路段追上慢車的時間取決於初始間距除相對速度。這個簡單關係能辨認待避需求，但實際時刻表還需加入停站、進路鎖閉與加減速；追及點不是允許兩車接近的安全距離。 追趕時間取決於起始間隔和兩列相對速度，不能只看快車速度。若兩列會停站或受訊號限制，速度必須改成分段函數，並把進路占用放回事件圖。 在既有線接續處檢查不同停站模式的追趕關係。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「快慢車追及與待避」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Catch-up time on a shared section is initial separation divided by relative speed. This relation identifies the need for overtaking opportunities, but real timetables also include stops, route locking and acceleration. The meeting point is not a permitted safe separation between trains. Catch-up time depends on starting separation and relative speed, not only the faster train’s speed. If either train stops or encounters signalling constraints, use piecewise speed functions and restore route occupation to the event diagram. Examine catch-up relationships where different stopping patterns join conventional infrastructure. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Fast-slow train catch-up” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：gap=12240 m; fast=60 m/s; slow=40 m/s；計算：catch_time=gap/(fast-slow)=612 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: gap=12240 m; fast=60 m/s; slow=40 m/s; calculation: catch_time=gap/(fast-slow)=612 s.","failure":"常見誤解：「快慢車平均速度不同也不會影響同線時刻表容量」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Different fast and slow train speeds do not affect shared-line timetable capacity.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「快慢車追及與待避」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Fast-slow train catch-up”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-33-k1","title":"快慢車追及與待避","titleEn":"Fast-slow train catch-up","text":"快車在同一路段追上慢車的時間取決於初始間距除相對速度。這個簡單關係能辨認待避需求，但實際時刻表還需加入停站、進路鎖閉與加減速；追及點不是允許兩車接近的安全距離。","textEn":"Catch-up time on a shared section is initial separation divided by relative speed. This relation identifies the need for overtaking opportunities, but real timetables also include stops, route locking and acceleration.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：快慢車平均速度不同也不會影響同線時刻表容量 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Different fast and slow train speeds do not affect shared-line timetable capacity. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「快慢車追及與待避」，下列哪一項敘述正確？","questionEn":"Which statement about \"Fast-slow train catch-up\" is correct?","options":["快車在同一路段追上慢車的時間取決於初始間距除相對速度。","快慢車平均速度不同也不會影響同線時刻表容量","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Catch-up time on a shared section is initial separation divided by relative speed.","Different fast and slow train speeds do not affect shared-line timetable capacity.","Squaring average current always gives the correct resistive heat load."],"answer":0,"explanation":"快車在同一路段追上慢車的時間取決於初始間距除相對速度。 其餘選項是常見誤解。","explanationEn":"Catch-up time on a shared section is initial separation divided by relative speed. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b310-v16-34","title":"快慢車追及與待避：定量估算","titleEn":"Fast-slow train catch-up: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-33"],"objective":"以數值模型估算「快慢車追及與待避」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Fast-slow train catch-up” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：gap=12240 m; fast=60 m/s; slow=40 m/s；計算：catch_time=gap/(fast-slow)=612 s。敏感度：gap 單獨增加百分之十至 13464 m，其餘固定，結果為 673.2 s。模型邊界：同向恆速且快車較快；不含號誌保護和停站。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: gap=12240 m; fast=60 m/s; slow=40 m/s; calculation: catch_time=gap/(fast-slow)=612 s. Sensitivity: gap, increase this input alone by ten percent, to 13464 m, with all other inputs fixed, gives 673.2 s. Model boundary: Same-direction constant speeds with a faster following train; signalling protection and stops are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用列車運行圖標出快慢車路徑與停站，把相交位置對照可待避地點，並核對道岔與站台實際占用時間。","observationEn":"How to cross-check: Plot fast and slow trajectories including stops, compare intersections with overtaking locations, and verify actual point and platform occupation times.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：gap=12240 m; fast=60 m/s; slow=40 m/s；計算：catch_time=gap/(fast-slow)=612 s。敏感度：gap 單獨增加百分之十至 13464 m，其餘固定，結果為 673.2 s。模型邊界：同向恆速且快車較快；不含號誌保護和停站。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: gap=12240 m; fast=60 m/s; slow=40 m/s; calculation: catch_time=gap/(fast-slow)=612 s. Sensitivity: gap, increase this input alone by ten percent, to 13464 m, with all other inputs fixed, gives 673.2 s. Model boundary: Same-direction constant speeds with a faster following train; signalling protection and stops are excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「快慢車追及與待避」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Fast-slow train catch-up\", which statement holds?","options":["長下坡只需通過一次緊急停車試驗就能驗證持續制動","原創假想算例，全部輸入均非本工程操作參數：gap=12240 m; fast=60 m/s; slow=40 m/s。","只要靜態接觸線高度正確就能保證高速受流品質"],"optionsEn":["One emergency stop test verifies continuous braking capability on a long descent.","Original hypothetical exercise.","Correct static contact-wire height alone guarantees good current collection at high speed."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：gap=12240 m; fast=60 m/s; slow=40 m/s；計算：catch_time=gap/(fast-slow)=612 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: gap=12240 m; fast=60 m/s; slow=40 m/s; calculation: catch_time=gap/(fast-slow)=612 s. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b310-v16-35","title":"快慢車追及與待避：試驗與驗證","titleEn":"Fast-slow train catch-up: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「快慢車追及與待避」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Fast-slow train catch-up” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用列車運行圖標出快慢車路徑與停站，把相交位置對照可待避地點，並核對道岔與站台實際占用時間。 以逐站到發時刻重建距離時間圖，核對起始間隔和各段速度，並標示待避占用。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Plot fast and slow trajectories including stops, compare intersections with overtaking locations, and verify actual point and platform occupation times. Rebuild a distance-time diagram from station arrivals and departures, verifying initial separation and segment speeds and marking passing occupation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：增加慢車停站與快車出發延後各一個情境，畫出時空圖，討論待避線能解決的衝突與仍存在的交叉進路限制。 再以本單元 gap 的對照值重算 catch_time，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Add a slow-train stop and a delayed fast departure as separate cases, draw time-distance diagrams, and distinguish conflicts solved by a loop from remaining crossing-route restrictions. Also recalculate catch_time for the alternative gap value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只看區間平均速度可能把追及位置判錯；慢車停站時間波動會改變待避窗口並將延誤傳給快車。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Using section-average speed can misplace the catch-up location; variable stopping time shifts overtaking windows and passes delay to the fast train. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"用列車運行圖標出快慢車路徑與停站，把相交位置對照可待避地點，並核對道岔與站台實際占用時間。 以逐站到發時刻重建距離時間圖，核對起始間隔和各段速度，並標示待避占用。","textEn":"Plot fast and slow trajectories including stops, compare intersections with overtaking locations, and verify actual point and platform occupation times. Rebuild a distance-time diagram from station arrivals and departures, verifying initial separation and segment speeds and marking passing occupation.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"增加慢車停站與快車出發延後各一個情境，畫出時空圖，討論待避線能解決的衝突與仍存在的交叉進路限制。 再以本單元 gap 的對照值重算 catch_time，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Add a slow-train stop and a delayed fast departure as separate cases, draw time-distance diagrams, and distinguish conflicts solved by a loop from remaining crossing-route restrictions. Also recalculate catch_time for the alternative gap value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「快慢車追及與待避」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Fast-slow train catch-up\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","降低目標速度時可忽略初速與目標速度的平方差","用列車運行圖標出快慢車路徑與停站，把相交位置對照可待避地點，並核對道岔與站台實際占用時間。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Reducing target speed allows the squared-speed difference to be ignored.","Plot fast and slow trajectories including stops, compare intersections with overtaking locations, and verify actual point and platform occupation times."],"answer":2,"explanation":"用列車運行圖標出快慢車路徑與停站，把相交位置對照可待避地點，並核對道岔與站台實際占用時間。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Plot fast and slow trajectories including stops, compare intersections with overtaking locations, and verify actual point and platform occupation times. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b310-v16-36","title":"快慢車追及與待避：失效診斷","titleEn":"Fast-slow train catch-up: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-35"],"objective":"從症狀倒推「快慢車追及與待避」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Fast-slow train catch-up” and propose discriminating checks, corrective actions and prevention.","instruction":"只看區間平均速度可能把追及位置判錯；慢車停站時間波動會改變待避窗口並將延誤傳給快車。 快慢車速度相同時不能用追趕公式分母，須重設工況。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Using section-average speed can misplace the catch-up location; variable stopping time shifts overtaking windows and passes delay to the fast train. Equal train speeds invalidate the catch-up denominator; redefine the operating case. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在既有線接續處檢查不同停站模式的追趕關係。","observationEn":"Link to the mechanism: Examine catch-up relationships where different stopping patterns join conventional infrastructure.","failure":"誤判風險：若相信「快慢車平均速度不同也不會影響同線時刻表容量」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Different fast and slow train speeds do not affect shared-line timetable capacity.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"只看區間平均速度可能把追及位置判錯；慢車停站時間波動會改變待避窗口並將延誤傳給快車。 快慢車速度相同時不能用追趕公式分母，須重設工況。","textEn":"Using section-average speed can misplace the catch-up location; variable stopping time shifts overtaking windows and passes delay to the fast train. Equal train speeds invalidate the catch-up denominator; redefine the operating case.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「快慢車追及與待避」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Fast-slow train catch-up\" shows distress, which diagnosis is most reasonable?","options":["只看區間平均速度可能把追及位置判錯；慢車停站時間波動會改變待避窗口並將延誤傳給快車。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Using section-average speed can misplace the catch-up location; variable stopping time shifts overtaking windows and passes delay to the fast train.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Squaring average current always gives the correct resistive heat load."],"answer":0,"explanation":"只看區間平均速度可能把追及位置判錯；慢車停站時間波動會改變待避窗口並將延誤傳給快車。 需以量測區分可能原因。","explanationEn":"Using section-average speed can misplace the catch-up location; variable stopping time shifts overtaking windows and passes delay to the fast train. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b310-v16-37","title":"電流平方損耗與散熱：機制與系統路徑","titleEn":"Current-squared losses and cooling: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-36"],"objective":"說明「電流平方損耗與散熱」如何影響法國東南高速鐵路的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Current-squared losses and cooling” governs forces, deformation, flow or signals in “LGV Sud-Est”, and map the relevant inputs, transfer paths and boundaries.","instruction":"導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。散熱取決於環境與接觸表面，電氣損耗量不能直接當成最終溫升。 此式是導體焦耳熱，並不是列車全部耗電。電阻會隨溫度改變，而並聯饋電使電流重新分配；比較兩方案時應保持相同功率交付邊界，避免只移轉損失位置。 把高峰電流與線路損失連結，檢查單一饋電路徑的限制。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「電流平方損耗與散熱」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate. Heat rejection depends on environment and contact surfaces; electrical loss alone is not a final temperature prediction. The expression represents conductor Joule heat, not all train consumption. Resistance changes with temperature, and parallel feeding redistributes current. Compare schemes at the same delivered-power boundary to avoid reporting loss relocation as an actual reduction. Link peak current to line losses and inspect the limits of a single feeding path. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Current-squared losses and cooling” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：current=1224 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=37.4544 kW。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1224 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=37.4544 kW.","failure":"常見誤解：「用平均電流代入平方損耗公式總能得到正確熱負荷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Squaring average current always gives the correct resistive heat load.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「電流平方損耗與散熱」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Current-squared losses and cooling”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b310-v16-37-k1","title":"電流平方損耗與散熱","titleEn":"Current-squared losses and cooling","text":"導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。散熱取決於環境與接觸表面，電氣損耗量不能直接當成最終溫升。","textEn":"Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate. Heat rejection depends on environment and contact surfaces; electrical loss alone is not a final temperature prediction.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：用平均電流代入平方損耗公式總能得到正確熱負荷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Squaring average current always gives the correct resistive heat load. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"關於「電流平方損耗與散熱」，下列哪一項敘述正確？","questionEn":"Which statement about \"Current-squared losses and cooling\" is correct?","options":["用平均電流代入平方損耗公式總能得到正確熱負荷","導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["Squaring average current always gives the correct resistive heat load.","Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":1,"explanation":"導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。 其餘選項是常見誤解。","explanationEn":"Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b310-v16-38","title":"電流平方損耗與散熱：定量估算","titleEn":"Current-squared losses and cooling: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-37"],"objective":"以數值模型估算「電流平方損耗與散熱」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Current-squared losses and cooling” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：current=1224 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=37.4544 kW。敏感度：current 單獨增加百分之十至 1346.4 A，其餘固定，結果為 45.31982 kW。模型邊界：恆定電阻且直流或等效均方根電流；不含散熱暫態。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1224 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=37.4544 kW. Sensitivity: current, increase this input alone by ten percent, to 1346.4 A, with all other inputs fixed, gives 45.31982 kW. Model boundary: Constant resistance with direct or equivalent RMS current; transient cooling is excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。","observationEn":"How to cross-check: Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b310-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：current=1224 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=37.4544 kW。敏感度：current 單獨增加百分之十至 1346.4 A，其餘固定，結果為 45.31982 kW。模型邊界：恆定電阻且直流或等效均方根電流；不含散熱暫態。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1224 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=37.4544 kW. Sensitivity: current, increase this input alone by ten percent, to 1346.4 A, with all other inputs fixed, gives 45.31982 kW. Model boundary: Constant resistance with direct or equivalent RMS current; transient cooling is excluded.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"依「電流平方損耗與散熱」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Current-squared losses and cooling\", which statement holds?","options":["速度增加一成時克服空氣阻力的功率只增加一成","無電區長度改變不會影響列車離開時的速度","原創假想算例，全部輸入均非本工程操作參數：current=1224 A; resistance=0.025 ohm。"],"optionsEn":["A ten percent speed increase raises aerodynamic power by only ten percent.","Changing the length of an unpowered section cannot change exit speed.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：current=1224 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=37.4544 kW。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1224 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=37.4544 kW. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b310-v16-39","title":"電流平方損耗與散熱：試驗與驗證","titleEn":"Current-squared losses and cooling: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「電流平方損耗與散熱」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Current-squared losses and cooling” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。 由電流時間歷程積分損失，量測導體溫度以校正電阻，並比對兩端功率差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation. Integrate losses over the current history, measure conductor temperature to correct resistance, and compare with the difference between terminal powers. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較固定電流與同平均值脈衝電流的均方根，計算兩種損耗，寫出溫度監測與電流紀錄需要同步的原因。 再以本單元 current 的對照值重算 loss，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare constant and pulsed currents with equal means, calculate their RMS losses, and explain why current and temperature records must be time-aligned. Also recalculate loss for the alternative current value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b310-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。 由電流時間歷程積分損失，量測導體溫度以校正電阻，並比對兩端功率差。","textEn":"Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation. Integrate losses over the current history, measure conductor temperature to correct resistance, and compare with the difference between terminal powers.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"比較固定電流與同平均值脈衝電流的均方根，計算兩種損耗，寫出溫度監測與電流紀錄需要同步的原因。 再以本單元 current 的對照值重算 loss，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare constant and pulsed currents with equal means, calculate their RMS losses, and explain why current and temperature records must be time-aligned. Also recalculate loss for the alternative current value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"要驗證「電流平方損耗與散熱」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Current-squared losses and cooling\"?","options":["以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。","不確定度太難估計，報告中只寫最佳值即可。","完全拘束的鋼軌升溫仍會無應力地自由伸長"],"optionsEn":["Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation.","Uncertainty is too hard to estimate, so the report may state only the best value.","A fully restrained rail still expands freely without stress when heated."],"answer":0,"explanation":"以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b310-v16-40","title":"電流平方損耗與散熱：失效診斷","titleEn":"Current-squared losses and cooling: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"prerequisiteIds":["b310-v16-39"],"objective":"從症狀倒推「電流平方損耗與散熱」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Current-squared losses and cooling” and propose discriminating checks, corrective actions and prevention.","instruction":"鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 尖峰電流不能用平均電流取代，否則平方項損失被低估。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. Peak current cannot be replaced by mean current without understating losses from the squared term. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把高峰電流與線路損失連結，檢查單一饋電路徑的限制。","observationEn":"Link to the mechanism: Link peak current to line losses and inspect the limits of a single feeding path.","failure":"誤判風險：若相信「用平均電流代入平方損耗公式總能得到正確熱負荷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Squaring average current always gives the correct resistive heat load.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b310-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 尖峰電流不能用平均電流取代，否則平方項損失被低估。","textEn":"Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. Peak current cannot be replaced by mean current without understating losses from the squared term.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]},{"id":"b310-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"]}],"quiz":{"question":"在「電流平方損耗與散熱」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Current-squared losses and cooling\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。","任何速度下增加超高都一定減少車內橫向加速度"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Loose joints increase resistance and concentrate heating.","Increasing cant always reduces lateral acceleration at every operating speed."],"answer":1,"explanation":"鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 需以量測區分可能原因。","explanationEn":"Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v16s-b310-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b310-background"],"curriculumVersion":16,"stepCount":40,"estimatedMinutes":1000,"flowDiagram":"assets/diagrams/v16-b310-zh.svg","flowDiagramEn":"assets/diagrams/v16-b310-en.svg"}};
